    private fun ranges(encoded: String): IntArray =
        encoded.split(',').map { it.toInt(16) }.toIntArray()

    fun isControl(cp: Int) = contains(CONTROL, cp)
    fun isExtend(cp: Int) = contains(EXTEND, cp)
    fun isPrepend(cp: Int) = contains(PREPEND, cp)
    fun isSpacingMark(cp: Int) = contains(SPACINGMARK, cp)
    fun isRegionalIndicator(cp: Int) = contains(REGIONAL_INDICATOR, cp)
    fun isExtendedPictographic(cp: Int) = contains(EXTENDED_PICTOGRAPHIC, cp)

    fun hangulType(cp: Int): HangulType = when {
        contains(L, cp) -> HangulType.L
        contains(V, cp) -> HangulType.V
        contains(T, cp) -> HangulType.T
        contains(LV, cp) -> HangulType.LV
        contains(LVT, cp) -> HangulType.LVT
        else -> HangulType.OTHER
    }

    enum class HangulType { L, V, T, LV, LVT, OTHER }

    private fun contains(ranges: IntArray, cp: Int): Boolean {
        var low = 0
        var high = ranges.size / 2 - 1
        while (low <= high) {
            val mid = (low + high) ushr 1
            val start = ranges[mid * 2]
            val end = ranges[mid * 2 + 1]
            when {
                cp < start -> high = mid - 1
                cp > end -> low = mid + 1
                else -> return true
            }
        }
        return false
    }
}
